const t={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:"用安全的“如果-则”规则自动化你的打印机。默认关闭；每条规则需自行启用。"}},empty:{t:0,b:{t:2,i:[{t:3}],s:"暂无规则。在下方添加一条，准备好后再启用它。"}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:"规则引擎已开启"}},off:{t:0,b:{t:2,i:[{t:3}],s:"规则引擎已关闭"}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:"开启"}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:"关闭"}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:"只有引擎和单条规则都开启后才会运行。"}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:"当打印完成时"}},print_error:{t:0,b:{t:2,i:[{t:3}],s:"当打印机出错时"}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:"当加热器温度升高超过"}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:"当加热器温度降低低于"}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:"记录一条通知"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"运行一条 g-code 命令"}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:"已启用"}},arm:{t:0,b:{t:2,i:[{t:3}],s:"已停用"}},edit:{t:0,b:{t:2,i:[{t:3}],s:"编辑"}},delete:{t:0,b:{t:2,i:[{t:3}],s:"删除"}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:"删除规则"}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:"规则名称"}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"例如：打印后关闭加热器"}},trigger:{t:0,b:{t:2,i:[{t:3}],s:"如果（触发条件）"}},action:{t:0,b:{t:2,i:[{t:3}],s:"则（动作）"}},heater:{t:0,b:{t:2,i:[{t:3}],s:"加热器"}},value:{t:0,b:{t:2,i:[{t:3}],s:"温度（°C）"}},message:{t:0,b:{t:2,i:[{t:3}],s:"消息"}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"显示在规则日志中"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"G-code"}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"例如：TURN_OFF_HEATERS"}},save:{t:0,b:{t:2,i:[{t:3}],s:"保存规则"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"取消"}},add:{t:0,b:{t:2,i:[{t:3}],s:"添加规则"}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:"近期活动"}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:"已通知"}},ran:{t:0,b:{t:2,i:[{t:3}],s:"已运行 g-code"}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:"已跳过（打印机忙）"}},error:{t:0,b:{t:2,i:[{t:3}],s:"错误"}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"指南"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"规则引擎指南"}},close:{t:0,b:{t:2,i:[{t:3}],s:"关闭"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"什么是规则引擎？"}},body:{t:0,b:{t:2,i:[{t:3}],s:"它会监视打印机，并在满足你设定的条件时执行动作 —— 例如，打印完成时记录一条备注，或关闭加热器。每条规则的形式是：如果（触发条件），则（执行动作）。"}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"它如何保持安全"}},body:{t:0,b:{t:2,i:[{t:3}],s:"引擎默认关闭，且每条规则都必须单独启用，因此不会有任何意外运行。规则在其条件首次成立时触发一次。G-code 动作仅在打印机空闲时运行 —— 打印过程中会被拒绝 —— 且每次结果都会记录。"}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"术语表"}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:"触发条件"}},def:{t:0,b:{t:2,i:[{t:3}],s:"启动规则的条件，例如一次打印完成，或加热器越过某一温度。"}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:"动作"}},def:{t:0,b:{t:2,i:[{t:3}],s:"规则触发时所做的事：记录一条通知，或运行一条 g-code 命令（仅在空闲时）。"}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:"已启用"}},def:{t:0,b:{t:2,i:[{t:3}],s:"处于开启状态的规则。已停用的规则会被保留，但永远不会触发。"}}}}}}};export{t as default};
